current_weapon = {"name": "m4a1", "pattern": m4a1}

class AutoTrigger:
    def __init__(self, ser, threshold, region_size, delay):
        self.last_avg_color = None

        self.ser = ser
        self.threshold = threshold
        self.region_size = region_size
        self.delay = delay

    def calculate_avg_color(self):
        with mss.mss() as sct:
            self.center_x = sct.monitors[1]["width"] // 2
            self.center_y = sct.monitors[1]["height"] // 2
            region = {
                "left": self.center_x - self.region_size // 2,
                "top": self.center_y - self.region_size // 2,
                "width": self.region_size,
                "height": self.region_size,
            }
            img = sct.grab(region)
            img_array = np.array(img)
            return np.mean(img_array, axis=(0, 1))

    def check_color_change(self, current_avg):
        if self.last_avg_color is None: return False
        color_diff = np.abs(current_avg - self.last_avg_color)
        return np.any(color_diff > self.threshold)

    def run(self):
        self.last_avg_color = self.calculate_avg_color()
        while True:
            current_avg = self.calculate_avg_color()
            if self.check_color_change(current_avg):
                time.sleep(self.delay / 1000)
                self.ser.write(b"8888,8888\n")
                self.ser.flush()
                self.active = False
                break

def do_control(ser, stop_event ,sens ,delay):
    for ammo in current_weapon["pattern"]:
        if stop_event.is_set():break
        try:
            ser.write(f"{int(2.5//sens*ammo['x'])},{int(2.5//sens*ammo['y'])}\n".encode())
            ser.flush()
        except serial.SerialTimeoutException:
            print("Write timeout occurred during control, skipping...")
            continue
        time.sleep(0.001 * ammo["d"]-delay)

def lets_cheat():
    config_path = os.path.join(os.path.dirname(__file__), 'configs.json')
    with open(config_path, 'r') as f:
        config = json.load(f)

    serial_config = config['serial']
    ser = serial.Serial(serial_config['port'], serial_config['baud'])
    control_config = config['auto_control']
    control_active = False
    stop_event = threading.Event()
    control_thread = None
    
    trigger_config = config['auto_trigger']
    trigger = AutoTrigger(
        ser,
        threshold=trigger_config['threshold'],
        region_size=trigger_config['region_size'],
        delay=trigger_config['delay']
    )

    trigger_active = False
    def on_trigger_press(event):
        nonlocal trigger_active
        if event.name == trigger_config["hotkey"]:
            if not trigger_active:
                trigger_active = True
                print("do auto_trigger")
                trigger.run()

    def on_trigger_release(event):
        nonlocal trigger_active
        if event.name == trigger_config["hotkey"]:
            trigger_active = False

    def on_control_press(event):
        nonlocal control_active, control_thread
        if event.name == control_config["hotkey"]:
            if not control_active:
                control_active = True
                stop_event.clear()
                print("do auto_control")
                control_thread = threading.Thread(target=do_control, args=(ser, stop_event ,control_config["sens"] ,control_config["delay"]))
                control_thread.start()

    def on_control_release(event):
        nonlocal control_active
        if event.name == control_config["hotkey"]:
            print("off auto_control")
            stop_event.set() 
            try:
                ser.write(b"9999,9999\n")
                ser.flush()
            except serial.SerialTimeoutException:
                print("Write timeout occurred when stopping control.")
            control_active = False
            
    def on_weapon_switch(e):
        if current_weapon["name"] == "m4a1":
            current_weapon["name"] = "ak47"
            current_weapon["pattern"] = ak47
        else:
            current_weapon["name"] = "m4a1"
            current_weapon["pattern"] = m4a1
        print(f"Switched to {current_weapon['name']}")

    keyboard.on_press_key(control_config["hotkey"], on_control_press)
    keyboard.on_release_key(control_config["hotkey"], on_control_release)
    keyboard.on_press_key(trigger_config["hotkey"], on_trigger_press)
    keyboard.on_release_key(trigger_config["hotkey"], on_trigger_release)
    keyboard.on_press_key(control_config["switch"], on_weapon_switch)
    keyboard.wait()

lets_cheat()
